//B"H
import { EVENT_TYPES, applyEventVisibility, loadEventVisibility, saveEventVisibility } from "../settings/eventVisibility.js";
import { checkNodeRelay, openRelayControl, openRelayLogin } from "../chatgpt/transport/nodeRelayFetch.js";
import { loadNodeRelaySettings, saveNodeRelaySettings } from "../chatgpt/transport/nodeRelaySettings.js";
import { automationGraphStore } from "./graphStore.js";
import { cloneDefaultAutomationGraph } from "./graphDefaults.js";
import { automationArchiveStore, downloadTextFile } from "./messageArchive.js";

export class AutomationPanel {
  constructor({ root, store, onChange }) {
    this.root = root;
    this.store = store;
    this.onChange = onChange;
    this.settings = store.load();
    this.graph = automationGraphStore.load();
    this.eventVisibility = loadEventVisibility();
    this.relaySettings = loadNodeRelaySettings();
    this.tab = "automation";
    applyEventVisibility(this.eventVisibility);
    this.render();
  }

  render() {
    this.root.innerHTML = `<div class="right-tabs">
      ${tab("automation", "Automation", this.tab)}${tab("graph", "Graph", this.tab)}${tab("archive", "Archive", this.tab)}${tab("settings", "Settings", this.tab)}${tab("trace", "Trace filters", this.tab)}
    </div><div class="right-panel-body">${this.body()}</div>`;
    this.bindTabs();
    this.bindAutomation();
    this.bindGraph();
    this.bindArchive();
    this.bindVisibility();
    this.bindRelay();
  }

  body() {
    if (this.tab === "settings") return `<h2>B"H Cockpit Settings</h2><p class="panel-note">The right drawer is now a multi-panel vessel.</p>${this.relayFields()}${this.visibilityFields()}`;
    if (this.tab === "trace") return `<h2>Message Trace Filters</h2><p class="panel-note">Disable noisy trace families without deleting them from history.</p>${this.visibilityFields()}`;
    if (this.tab === "graph") return this.graphFields();
    if (this.tab === "archive") return this.archiveFields();
    return `<h2>Automation Pipeline</h2>${field("enabled", "Enable auto-continue", "checkbox", this.settings.enabled)}${field("maxTurns", "Max turns", "number", this.settings.maxTurns)}${field("delayMs", "Delay ms", "number", this.settings.delayMs)}<label class="automation-field prompt-field">Prompt<textarea data-auto="prompt" rows="7">${text(this.settings.prompt)}</textarea></label><div class="automation-status" id="automation-status">${this.settings.enabled ? "automation armed" : "automation off"}</div>`;
  }

  graphFields() {
    return `<section class="automation-graph-panel">
      <h2>Automation Graph</h2>
      <p class="panel-note">Build rules like: if the last AI message contains text, send this prompt; otherwise stop/archive. JSON is the source of truth and can be pasted or edited.</p>
      <div class="graph-toolbar">
        <button type="button" data-graph-action="add-send">+ Send</button>
        <button type="button" data-graph-action="add-condition">+ Condition</button>
        <button type="button" data-graph-action="add-archive">+ Archive</button>
        <button type="button" data-graph-action="add-stop">+ Stop</button>
        <button type="button" data-graph-action="reset">Reset</button>
        <button type="button" data-graph-action="save-forms">Save Forms</button>
        <button type="button" data-graph-action="save-json">Save JSON</button>
        <button type="button" data-graph-action="download-json">Download JSON</button>
      </div>
      <label class="automation-field graph-start-field">Start node <select data-graph-start>${nodeOptions(this.graph.nodes, this.graph.start)}</select></label>
      <div class="graph-canvas">${this.graph.nodes.map(nodeEditor).join("")}</div>
      <label class="automation-field graph-json-field">Graph JSON<textarea data-graph-json rows="14">${text(JSON.stringify(this.graph, null, 2))}</textarea></label>
      <div class="automation-status" id="graph-status">graph ready: ${this.graph.nodes.length} node(s)</div>
    </section>`;
  }

  archiveFields() {
    return `<section class="automation-archive-panel">
      <h2>Automation Archive</h2>
      <p class="panel-note">Assistant replies are stored in IndexedDB for graph runs. Download or clear the archive here.</p>
      <div class="graph-toolbar">
        <button type="button" data-archive-action="download">Download archive JSON</button>
        <button type="button" data-archive-action="clear">Clear archive</button>
        <button type="button" data-archive-action="count">Count messages</button>
      </div>
      <div class="automation-status" id="archive-status">archive ready</div>
    </section>`;
  }

  relayFields() {
    const enabled = this.relaySettings.enabled ? "checked" : "";
    return `<section class="automation-card relay-card">
      <h3>ChatGPT transport</h3>
      <p class="panel-note">Use the extension bridge, or connect to the experimental split-browser relay already running from <code>geelooy/ai/relay/split-browser</code>.</p>
      <label class="automation-field">Relay URL<input data-relay="url" value="${attr(this.relaySettings.url)}"></label>
      <label class="automation-field"><input data-relay="enabled" type="checkbox" ${enabled}> Use Node relay instead of extension</label>
      <div class="relay-actions"><button type="button" data-relay-action="health">Check split relay</button><button type="button" data-relay-action="control">Get localhost control URL</button><button type="button" data-relay-action="extension">Switch back to extension</button></div>
      <div class="automation-status" id="relay-status">${this.relaySettings.enabled ? "Node relay selected" : "Extension bridge selected"}</div>
    </section>`;
  }

  visibilityFields() {
    return `<div class="event-filter-grid">${EVENT_TYPES.map(type => `<label class="automation-field event-filter"><input data-event-type="${type}" type="checkbox" ${this.eventVisibility[type] !== false ? "checked" : ""}> Show ${label(type)}</label>`).join("")}</div>`;
  }

  bindTabs() { this.root.querySelectorAll("[data-tab]").forEach(btn => btn.onclick = () => { this.tab = btn.dataset.tab; this.render(); }); }
  bindAutomation() { this.root.querySelectorAll("[data-auto]").forEach(input => input.oninput = () => this.captureAutomation()); }
  bindVisibility() { this.root.querySelectorAll("[data-event-type]").forEach(input => input.onchange = () => this.captureVisibility()); }

  bindGraph() {
    this.root.querySelectorAll("[data-graph-action]").forEach(button => button.onclick = () => this.handleGraphAction(button.dataset.graphAction));
  }

  bindArchive() {
    this.root.querySelectorAll("[data-archive-action]").forEach(button => button.onclick = () => this.handleArchiveAction(button.dataset.archiveAction));
  }

  bindRelay() {
    this.root.querySelectorAll("[data-relay]").forEach(input => input.oninput = () => this.captureRelay());
    this.root.querySelectorAll("[data-relay-action]").forEach(button => button.onclick = () => this.handleRelayAction(button.dataset.relayAction));
  }

  captureAutomation() {
    const next = {};
    this.root.querySelectorAll("[data-auto]").forEach(input => next[input.dataset.auto] = input.type === "checkbox" ? input.checked : cast(input.value));
    this.settings = this.store.save(next);
    this.onChange?.(this.settings);
  }

  handleGraphAction(action) {
    const status = this.root.querySelector("#graph-status");
    try {
      if (action === "reset") this.graph = automationGraphStore.save(cloneDefaultAutomationGraph());
      if (action === "add-send") this.graph = automationGraphStore.save({ ...this.graph, nodes: [...this.graph.nodes, newNode("send", this.graph.nodes.length)] });
      if (action === "add-condition") this.graph = automationGraphStore.save({ ...this.graph, nodes: [...this.graph.nodes, newNode("condition", this.graph.nodes.length)] });
      if (action === "add-archive") this.graph = automationGraphStore.save({ ...this.graph, nodes: [...this.graph.nodes, newNode("archive", this.graph.nodes.length)] });
      if (action === "add-stop") this.graph = automationGraphStore.save({ ...this.graph, nodes: [...this.graph.nodes, newNode("stop", this.graph.nodes.length)] });
      if (action === "save-forms") this.graph = automationGraphStore.save(this.captureGraphForms());
      if (action?.startsWith?.("delete:")) this.graph = automationGraphStore.save({ ...this.graph, nodes: this.graph.nodes.filter(node => node.id !== action.slice(7)) });
      if (action === "save-json") this.graph = automationGraphStore.save(JSON.parse(this.root.querySelector("[data-graph-json]").value));
      if (action === "download-json") downloadTextFile("BH_automation_graph.json", JSON.stringify(this.graph, null, 2));
      status && (status.textContent = "graph saved");
      this.render();
    } catch (error) {
      status && (status.textContent = `graph error: ${error.message || error}`);
    }
  }

  captureGraphForms() {
    const start = this.root.querySelector("[data-graph-start]")?.value || this.graph.start;
    const nodes = [...this.root.querySelectorAll("[data-graph-node]")].map(card => {
      const node = {};
      card.querySelectorAll("[data-node-field]").forEach(input => {
        node[input.dataset.nodeField] = input.type === "checkbox" ? input.checked : input.value;
      });
      return node;
    });
    return { version: 1, start, nodes };
  }

  captureGraphForms() {
    const start = this.root.querySelector("[data-graph-start]")?.value || this.graph.start;
    const nodes = [...this.root.querySelectorAll("[data-graph-node]")].map(card => {
      const node = {};
      card.querySelectorAll("[data-node-field]").forEach(input => {
        node[input.dataset.nodeField] = input.type === "checkbox" ? input.checked : input.value;
      });
      return node;
    });
    return { version: 1, start, nodes };
  }

  async handleArchiveAction(action) {
    const status = this.root.querySelector("#archive-status");
    if (action === "download") {
      downloadTextFile("BH_automation_archive.json", await automationArchiveStore.exportJson());
      status.textContent = "archive downloaded";
    }
    if (action === "clear") {
      await automationArchiveStore.clear();
      status.textContent = "archive cleared";
    }
    if (action === "count") {
      const list = await automationArchiveStore.list();
      status.textContent = `${list.length} archived message(s)`;
    }
  }

  captureVisibility() {
    const next = { ...this.eventVisibility };
    this.root.querySelectorAll("[data-event-type]").forEach(input => next[input.dataset.eventType] = input.checked);
    this.eventVisibility = saveEventVisibility(next);
  }

  captureRelay() {
    const next = {};
    this.root.querySelectorAll("[data-relay]").forEach(input => next[input.dataset.relay] = input.type === "checkbox" ? input.checked : input.value);
    this.relaySettings = saveNodeRelaySettings(next);
    this.relayReport(this.relaySettings.enabled ? "Node relay selected" : "Extension bridge selected");
  }

  async handleRelayAction(action) {
    if (action === "extension") { this.relaySettings = saveNodeRelaySettings({ enabled: false }); this.relayReport("Extension bridge selected"); this.render(); return; }
    if (action === "control" || action === "login") { this.relaySettings = saveNodeRelaySettings({ ...this.relaySettings, enabled: true }); this.relayReport("Opening localhost control URL…"); const url = action === "login" ? await openRelayLogin() : await openRelayControl(); this.relayReport(`Split relay control opened: ${url}`); this.render(); return; }
    if (action === "health") { this.relayReport("Checking relay…"); const ok = await checkNodeRelay(); this.relayReport(ok ? "Node relay is reachable" : "Node relay not reachable yet. Run: node chatgpt-node-relay.cjs"); }
  }

  getSettings() { return this.settings; }
  report(text) { const status = this.root.querySelector("#automation-status"); if (status) status.textContent = text; }
  relayReport(text) { const status = this.root.querySelector("#relay-status"); if (status) status.textContent = text; }
}

function nodeEditor(node, index, list = []) {
  const options = nodeOptions(list.length ? list : [node], "");
  return `<article class="graph-node graph-node-${attr(node.type)}" data-graph-node>
    <div class="graph-node-head"><strong>${text(node.label || node.id)}</strong><button type="button" data-graph-action="delete:${attr(node.id)}">Delete</button></div>
    <div class="graph-node-grid">
      ${nodeInput("id", "ID", node.id)}
      ${nodeSelect("type", "Type", node.type, ["condition", "send", "archive", "stop"])}
      ${nodeInput("label", "Label", node.label)}
      ${nodeInput("archiveTag", "Archive tag", node.archiveTag)}
      ${nodeInput("match", node.regex ? "Regex" : "Contains text", node.match)}
      ${nodeCheckbox("regex", "Use regex", node.regex)}
      ${nodeInput("flags", "Regex flags", node.flags || "i")}
      ${nodeCheckbox("negate", "Negate condition", node.negate)}
      ${nodeSelect("onTrue", "On true", node.onTrue, ["", ...list.map(n => n.id)])}
      ${nodeSelect("onFalse", "On false", node.onFalse, ["", ...list.map(n => n.id)])}
      ${nodeSelect("next", "Next", node.next, ["", ...list.map(n => n.id)])}
    </div>
    <label class="automation-field graph-node-prompt">Prompt<textarea data-node-field="prompt" rows="4">${text(node.prompt || "")}</textarea></label>
    <p>${text(describeNode(node))}</p>
  </article>`;
}
function describeNode(node) { if (node.type === "condition") return `${node.negate ? "unless" : "if"} last message contains "${node.match}" → ${node.onTrue || "?"} / ${node.onFalse || "?"}`; if (node.type === "send") return `send: ${node.prompt || "settings prompt"}`; if (node.type === "archive") return `archive as ${node.archiveTag || node.id} then ${node.next || "stop"}`; return "stop"; }
function nodeInput(name, labelText, value = "") { return `<label class="automation-field">${labelText}<input data-node-field="${name}" value="${attr(value)}"></label>`; }
function nodeCheckbox(name, labelText, value = false) { return `<label class="automation-field"><input data-node-field="${name}" type="checkbox" ${value ? "checked" : ""}> ${labelText}</label>`; }
function nodeSelect(name, labelText, value, values) { return `<label class="automation-field">${labelText}<select data-node-field="${name}">${values.map(item => `<option value="${attr(item)}" ${item === value ? "selected" : ""}>${text(item || "—")}</option>`).join("")}</select></label>`; }
function nodeOptions(nodes = [], selected = "") { return nodes.map(node => `<option value="${attr(node.id)}" ${node.id === selected ? "selected" : ""}>${text(node.label || node.id)}</option>`).join(""); }
function newNode(type, index) { const id = `${type}-${index + 1}`; return { id, type, label: `${type} ${index + 1}`, match: "", negate: false, prompt: type === "send" ? "continue with the next precise verified step" : "", archiveTag: type === "archive" || type === "send" ? "graph" : "", onTrue: "", onFalse: "", next: "" }; }
function tab(name, labelText, active) { return `<button type="button" data-tab="${name}" class="${active === name ? "active" : ""}">${labelText}</button>`; }
function field(name, labelText, type, value) { const checked = type === "checkbox" && value ? "checked" : ""; const val = type === "checkbox" ? "" : `value="${attr(value)}"`; return `<label class="automation-field">${labelText}<input data-auto="${name}" type="${type}" ${val} ${checked}></label>`; }
function cast(value) { return /^\d+$/.test(String(value)) ? Number(value) : value; }
function attr(value) { return String(value ?? "").replace(/[&<>"]/g, c => ({ "&": "&amp;", "<": "&lt;", ">": "&gt;", '"': "&quot;" }[c])); }
function text(value) { return String(value ?? "").replace(/[&<>]/g, c => ({ "&": "&amp;", "<": "&lt;", ">": "&gt;" }[c])); }
function label(type) { return ({ awtsmoos_tool: "Awtsmoos tool calls", agent_tool: "Agent tool calls", tool_call: "Generic tool calls", tool_result: "Tool results", status: "Status packets", raw: "Raw packets", hidden: "Hidden messages", code: "Code payloads", thinking: "Thinking traces", oauth: "OAuth prompts" })[type] || type.replace(/_/g, " "); }

geelooy/ai/css/automation-futuristic.css.content:
/* B"H
  Chapter 112: The Automation Panel Became A Circuit Of Living Sapphires.
*/
#automation-panel .right-panel-body {
  background:
    radial-gradient(circle at 20% 0%, rgba(34,211,238,.16), transparent 32%),
    radial-gradient(circle at 90% 15%, rgba(168,85,247,.14), transparent 36%),
    linear-gradient(180deg, rgba(2,6,23,.38), rgba(2,6,23,.82));
}

#automation-panel h2 {
  font-size: 1.22rem;
  letter-spacing: -.035em;
  text-shadow: 0 0 22px rgba(103,232,249,.24);
}

#automation-panel .automation-field {
  position: relative;
  padding: .72rem .78rem;
  border: 1px solid rgba(125,211,252,.18);
  border-radius: 1.05rem;
  background: linear-gradient(135deg, rgba(15,23,42,.70), rgba(8,47,73,.22));
  box-shadow: inset 0 1px 0 rgba(255,255,255,.05), 0 10px 26px rgba(0,0,0,.18);
}

#automation-panel .automation-field:has(input[type="checkbox"]) {
  grid-template-columns: 3.15rem minmax(0, 1fr);
  align-items: center;
  cursor: pointer;
}

#automation-panel .automation-field input[type="checkbox"] {
  appearance: none;
  width: 2.75rem !important;
  height: 1.42rem !important;
  margin: 0;
  border-radius: 999px;
  border: 1px solid rgba(148,163,184,.38);
  background: linear-gradient(180deg, rgba(30,41,59,.98), rgba(15,23,42,.98));
  box-shadow: inset 0 2px 8px rgba(0,0,0,.42), 0 0 0 1px rgba(255,255,255,.025);
  transition: border-color .16s ease, box-shadow .16s ease, background .16s ease;
}

#automation-panel .automation-field input[type="checkbox"]::before {
  content: "";
  display: block;
  width: 1.02rem;
  height: 1.02rem;
  margin: .15rem;
  border-radius: 999px;
  background: linear-gradient(135deg, #e2e8f0, #94a3b8);
  box-shadow: 0 3px 10px rgba(0,0,0,.35);
  transition: transform .16s ease, background .16s ease;
}

#automation-panel .automation-field input[type="checkbox"]:checked {
  border-color: rgba(34,211,238,.78);
  background: linear-gradient(135deg, rgba(14,165,233,.92), rgba(16,185,129,.88));
  box-shadow: 0 0 24px rgba(34,211,238,.24), inset 0 1px 6px rgba(255,255,255,.22);
}

#automation-panel .automation-field input[type="checkbox"]:checked::before {
  transform: translateX(1.28rem);
  background: linear-gradient(135deg, #ffffff, #cffafe);
}

#automation-panel .automation-field input:not([type="checkbox"]),
#automation-panel .automation-field textarea,
#automation-panel .automation-field select {
  width: 100%;
  box-sizing: border-box;
  resize: vertical;
  border: 1px solid rgba(125,211,252,.22);
  border-radius: .95rem;
  background: rgba(2,6,23,.74);
  color: #effdff;
  padding: .72rem .82rem;
  outline: none;
  line-height: 1.45;
  box-shadow: inset 0 1px 8px rgba(0,0,0,.28);
}

#automation-panel .automation-field textarea {
  min-height: 9.5rem;
  font-family: ui-monospace, SFMono-Regular, Menlo, Consolas, monospace;
  font-size: .86rem;
}

#automation-panel .automation-field input:focus,
#automation-panel .automation-field textarea:focus,
#automation-panel .automation-field select:focus {
  border-color: rgba(103,232,249,.86);
  box-shadow: 0 0 0 3px rgba(34,211,238,.13), 0 0 28px rgba(34,211,238,.12), inset 0 1px 8px rgba(0,0,0,.25);
}

#automation-panel .automation-status {
  border-radius: 1rem;
  border: 1px solid rgba(52,211,153,.34);
  background: linear-gradient(135deg, rgba(6,78,59,.35), rgba(8,47,73,.2)), rgba(2,6,23,.58);
  color: #bbf7d0;
  box-shadow: 0 0 28px rgba(16,185,129,.10), inset 0 1px 0 rgba(255,255,255,.05);
}

#automation-panel .right-tabs button {
  isolation: isolate;
  position: relative;
  overflow: hidden;
}

#automation-panel .right-tabs button::after {
  content: "";
  position: absolute;
  inset: 0;
  opacity: 0;
  background: linear-gradient(90deg, transparent, rgba(255,255,255,.22), transparent);
  transform: translateX(-120%);
}

#automation-panel .right-tabs button:hover::after,
#automation-panel .right-tabs button.active::after {
  opacity: 1;
  animation: automationSweep 1.6s ease infinite;
}

.automation-graph-panel,
.automation-archive-panel {
  display: grid;
  gap: .9rem;
}

.graph-toolbar,
.relay-actions {
  display: flex;
  flex-wrap: wrap;
  gap: .45rem;
}

.graph-toolbar button,
.relay-actions button {
  border: 1px solid rgba(34,211,238,.28);
  border-radius: 999px;
  background: linear-gradient(135deg, rgba(14,165,233,.18), rgba(168,85,247,.18));
  color: #e0fbff;
  padding: .55rem .78rem;
  box-shadow: 0 10px 24px rgba(0,0,0,.16), inset 0 1px 0 rgba(255,255,255,.07);
}

.graph-toolbar button:hover,
.relay-actions button:hover {
  transform: translateY(-1px);
  border-color: rgba(125,211,252,.58);
  box-shadow: 0 14px 32px rgba(34,211,238,.12), inset 0 1px 0 rgba(255,255,255,.12);
}

.graph-canvas {
  position: relative;
  display: grid;
  gap: .72rem;
  padding: .8rem;
  border: 1px solid rgba(125,211,252,.16);
  border-radius: 1.25rem;
  background:
    linear-gradient(rgba(125,211,252,.055) 1px, transparent 1px),
    linear-gradient(90deg, rgba(125,211,252,.055) 1px, transparent 1px),
    rgba(2,6,23,.42);
  background-size: 22px 22px;
  box-shadow: inset 0 0 32px rgba(34,211,238,.045);
}

.graph-node {
  position: relative;
  display: grid;
  gap: .35rem;
  padding: .85rem .9rem .85rem 1.05rem;
  border-radius: 1.05rem;
  border: 1px solid rgba(148,163,184,.22);
  background: linear-gradient(135deg, rgba(15,23,42,.9), rgba(8,47,73,.52));
  box-shadow: 0 18px 36px rgba(0,0,0,.22), inset 0 1px 0 rgba(255,255,255,.05);
}

.graph-node::before {
  content: "";
  position: absolute;
  inset-block: .75rem;
  inset-inline-start: .48rem;
  width: .2rem;
  border-radius: 999px;
  background: linear-gradient(180deg, #22d3ee, #a78bfa);
  box-shadow: 0 0 18px rgba(34,211,238,.4);
}

.graph-node strong {
  color: #f8fdff;
  font-size: .96rem;
}

.graph-node span,
.graph-node code,
.graph-node p {
  color: rgba(226,232,240,.76);
  font-size: .78rem;
}

.graph-node code {
  width: fit-content;
  max-width: 100%;
  overflow-wrap: anywhere;
  padding: .18rem .45rem;
  border-radius: 999px;
  border: 1px solid rgba(34,211,238,.18);
  background: rgba(2,6,23,.62);
}

.graph-node-condition { border-color: rgba(250,204,21,.30); }
.graph-node-condition::before { background: linear-gradient(180deg, #fde047, #fb7185); box-shadow: 0 0 18px rgba(250,204,21,.32); }
.graph-node-send { border-color: rgba(34,211,238,.30); }
.graph-node-stop { border-color: rgba(248,113,113,.32); }
.graph-node-stop::before { background: linear-gradient(180deg, #fb7185, #ef4444); }
.graph-node-archive { border-color: rgba(52,211,153,.30); }
.graph-node-archive::before { background: linear-gradient(180deg, #34d399, #22d3ee); }

.graph-json-field textarea {
  min-height: 17rem !important;
  tab-size: 2;
  white-space: pre;
}

@keyframes automationSweep { to { transform: translateX(120%); } }
